/// <summary>
/// CB756_ValidationOfABNToATOSystem.
/// The class <c>METABNValidation</c> contains logic to validate ABN.
/// </summary>
class METABNValidation
{
    CustTable               custTable;
    METATOWebServiceHelper  atoWebServiceHelper;
    AddressCountryRegionId  countryRegionId;
    TransDate               todayDate;

}

Method.Source:
    /// <summary>
    /// Acts as an entry point when this class is invoked from form.
    /// </summary>
    /// <param name = "_args"> <c>Arg</c>. </param>
    public static void main(Args _args)
    {
        METABNValidation abnValidation;
        CustTable        custTable;

        if (_args.record().TableId != tableNum(CustTable))
        {
            throw error(Error::wrongUseOfFunction(funcName()));
        }

        custTable = _args.record();
        abnValidation = METABNValidation::construct(custTable);

        abnValidation.run();
    }

/// <summary>
/// Gets and sets CustTable.
/// </summary>
/// <param name = "_custTable">CustTable.</param>
/// <returns>CustTable.</returns>
public CustTable parmCustTable(CustTable _custTable = custTable)
{
    custTable = _custTable;
    return custTable;
}

    /// <summary>
    /// Constructs and returns <c>METABNValidation</c> object.
    /// </summary>
    /// <param name = "_custTable">CustTable.</param>
    /// <returns> <c>METABNValidation</c> object. </returns>
    public static METABNValidation construct(CustTable _custTable)
    {
        METABNValidation abnValidation = new METABNValidation();

        abnValidation.parmCustTable(_custTable);

        return abnValidation;
    }

    /// <summary>
    /// Runs the main process.
    /// </summary>
    public void run()
    {
        #OCCRetryCount

        if (!this.isValidationRequired())
        {
            return;
        }

        try
        {
            ttsbegin;

            this.init();
            this.validateABN();
            this.validateRegistrationId();

            info(strFmt("@MET:ABNValidationComplete", custTable.AccountNum));

            ttscommit;

        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch 
        {
            error(strFmt("@MET:ABNValidationError", custTable.AccountNum));
        }

        FormDataUtil::getFormDataSource(custTable).reread();
    }

/// <summary>
/// Initializes global variables.
/// </summary>
private void init()
{
    atoWebServiceHelper = METATOWebServiceHelper::construct(custTable);
    countryRegionId = CompanyInfo::find().postalAddress().CountryRegionId;
    todayDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
}

    /// <summary>
    /// Checks if ABN validation is required or not.
    /// </summary>
    /// <returns>True, if ABN validation required; otherwise, false.</returns>
    private boolean isValidationRequired()
    {
        CredManAccountStatusTable accountStatusTable;

        if (!custTable.CredManAccountStatusId)
        {
            return false;
        }

        select firstonly RecId from accountStatusTable
            where accountStatusTable.CustAccountStatusId == custTable.CredManAccountStatusId
            &&    accountStatusTable.METABNValidation != METABNValidationType::None;

        return (accountStatusTable.RecId != 0);
    }

    /// <summary>
    /// Validats ABN.
    /// </summary>
    private void validateABN()
    {
        TaxVATNumTable taxVatNumTable;

        if (!custTable.VATNum)
        {
            return;
        }

        if (atoWebServiceHelper.callWebService(custTable.VATNum))
        {
            taxVatNumTable = TaxVATNumTable::find(custTable.VATNum, countryRegionId);
            atoWebServiceHelper.updateTaxVATNumTable(taxVatNumTable);
        }

    }

    /// <summary>
    /// Validates registration Id.
    /// </summary>
    private void validateRegistrationId()
    {
        TaxRegistration                      taxRegistration;
        TaxRegistrationTypeApplicabilityRule taxRegistrationTypeApplicabilityRule;
        DirPartyLocation                     dirPartyLocation;
        DirPartyTable                        dirPartyTable;
        CustTable                            customer;

        while select firstonly validTimeState(todayDate) taxRegistration
            exists join taxRegistrationTypeApplicabilityRule
                where taxRegistration.TaxRegistrationTypeApplicabilityRule == taxRegistrationTypeApplicabilityRule.RecId
                &&    taxRegistrationTypeApplicabilityRule.METValidateABNWithATO == NoYes::Yes
                &&    taxRegistrationTypeApplicabilityRule.CountryRegionId == countryRegionId
            exists join dirPartyLocation
                where taxRegistration.DirPartyLocation == dirPartyLocation.RecId
                   && dirPartyLocation.IsPrimary == NoYes::Yes
            exists join dirPartyTable
                where dirPartyLocation.Party == dirPartyTable.RecId
            exists join customer
                where customer.Party == dirPartyTable.RecId
                   && customer.AccountNum == custTable.AccountNum
        {
            if (atoWebServiceHelper.callWebService(taxRegistration.RegistrationNumber))
            {
                atoWebServiceHelper.updateTaxRegistration(taxRegistration);
            }
        }
    }
